import { useState, useEffect, useRef } from "react";
type Report = { id: string; praia: string; autor: string; tamanho: string; vento: string; texto: string; foto: string; createdAt: string; aoVivoUrl?: string; };
type Cam = { id: string; praia: string; label: string; liveUrl: string; plataforma: "youtube" | "instagram"; };
//type Noticia = { id: string; titulo: string; resumo: string; foto: string; fonte: string; data: string; };
const PRAIAS = ["Itamambuca","Vermelha do Norte","Vermelha do Centro","Félix","Prumirim","Toninhas","Tenório","Praia Grande","Perequê Açú","Domingas Dias","Sununga"];
const INFORMAL: Record<string,string> = {"Itamambuca":"itamambuca","Vermelha do Norte":"vermelhinha do norte","Vermelha do Centro":"vermelhinha do centro","Félix":"felixzinho","Prumirim":"prumirim","Toninhas":"toninhas","Tenório":"tenório","Praia Grande":"praiagrandão","Perequê Açú":"pereque","Domingas Dias":"domingas","Sununga":"sununga"};
const TAMANHO_FALA: Record<string,string> = {"0,5m":"meio metrinho maralzinho","0,8m":"quase 1m glass","1,0m":"1 metrinho cavado","1,5m":"1,5m pressão!","2,0m":"2m tá monstro"};
const COORDS: Record<string,{fundo:string,nivel:string}> = {"Itamambuca": {fundo:"Areia", nivel:"Intermediário/Avançado"},"Vermelha do Norte": {fundo:"Areia e pedra", nivel:"Avançado"},"Vermelha do Centro": {fundo:"Areia", nivel:"Intermediário"},"Félix": {fundo:"Areia", nivel:"Iniciante"},"Prumirim": {fundo:"Areia", nivel:"Iniciante"},"Toninhas": {fundo:"Areia", nivel:"Iniciante"},"Tenório": {fundo:"Areia", nivel:"Intermediário"},"Praia Grande": {fundo:"Areia", nivel:"Iniciante"},"Perequê Açú": {fundo:"Areia", nivel:"Iniciante"},"Domingas Dias": {fundo:"Areia", nivel:"Intermediário"},"Sununga": {fundo:"Areia", nivel:"Avançado"}};
type PicoData = { praia: string; onda: string; vento: string; periodo: string; mare: string; tendencia: "subindo" | "descendo" | "estavel"; variacao: string; fundo: string; nivel: string; crowd: string; };
function getYoutubeEmbed(url: string): string | null { try { const u = new URL(url); if (u.hostname.includes("youtu.be")) return "https://www.youtube.com/embed/"+u.pathname.slice(1); if (u.searchParams.get("v")) return "https://www.youtube.com/embed/"+u.searchParams.get("v"); if (url.includes("/live/")) { const id = url.split("/live/")[1]?.split("?")[0]; if(id) return "https://www.youtube.com/embed/"+id; } return null; } catch { return null; } }
const GRAFICO_HOJE = [{ hora: "06h", onda: 0.6, vento: 0.4, mare: 0.3 },{ hora: "09h", onda: 0.8, vento: 0.5, mare: 0.9 },{ hora: "12h", onda: 1.2, vento: 1.1, mare: 1.4 },{ hora: "15h", onda: 1.5, vento: 1.3, mare: 1.2 },{ hora: "18h", onda: 1.1, vento: 0.8, mare: 0.6 },{ hora: "21h", onda: 0.9, vento: 0.5, mare: 0.4 },];
function GraficoOndaVentoMare({ data }: { data: typeof GRAFICO_HOJE }){ const max = 2.5; const h = 110; const w = 520; const padL = 30; const padB = 18; const chartW = w - padL - 5; const chartH = h - padB - 5; const toX = (i:number) => padL + (i/(data.length-1))*chartW; const toY = (v:number) => 5 + chartH - (v/max)*chartH; const path = (key: "onda"|"vento"|"mare") => data.map((d,i)=> (i===0?"M":"L")+" "+toX(i)+" "+toY(d[key])).join(" "); const ticks = [0,0.5,1,1.5,2]; return (<div className="w-full bg-white rounded-[10px] border p-2"><div className="flex justify-between items-center mb-1"><p className="font-black text-[9px] text-[#2a5bd7]">📊 Onda/Vento/Maré</p></div><svg viewBox={"0 0 "+w+" "+h} className="w-full h-[80px]">{ticks.map(t=>(<g key={t}><line x1={padL} y1={toY(t)} x2={w} y2={toY(t)} stroke="#e5e7eb" strokeDasharray="3 3" /><text x={2} y={toY(t)+2} fontSize="8" fill="#6b7280" fontWeight="bold">{t===0?"0":t}</text></g>))}<path d={path("onda")} fill="none" stroke="#3b82f6" strokeWidth="2.5" /><path d={path("vento")} fill="none" stroke="#10b981" strokeWidth="2" strokeDasharray="4 3" /><path d={path("mare")} fill="none" stroke="#f59e0b" strokeWidth="2" />{data.map((d,i)=><text key={i} x={toX(i)} y={h-2} fontSize="7" fill="#374151" textAnchor="middle" fontWeight="bold">{d.hora}</text>)}</svg></div>);}
const BG_PONTO = "data:image/webp;base64,";
const BG_MEDINA = "data:image/webp;base64,";
const BG_SLATER = "data:image/jpeg;base64,";
const BG_ANDY = "data:image/jpeg;base64,";
const BG_JOHN = "data:image/jpeg;base64,";
const BG_ITALO = "data:image/jpeg;base64,";
const NOTICIAS = [{ id:"1", titulo:"Swell de sul chega com 1,5m", resumo:"Subida até quarta 13s.", foto:"https://images.unsplash.com/photo-1502680390542-bdb6c82a8aea?w=600&h=340&fit=crop", fonte:"Surfguru", data:"hoje" },{ id:"2", titulo:"Vermelha do Centro crowd baixo", resumo:"Glass e terral manhã.", foto:"https://images.unsplash.com/photo-1519046904884-53103b34f59d?w=600&h=340&fit=crop", fonte:"My Surf", data:"hoje" },];

export default function App(){
  const [reports,setReports]=useState<Report[]>(()=>{
    const s=localStorage.getItem("ms-ubatuba-reports-v3");
    if(s){ try{return JSON.parse(s)}catch{}}
    return [
      { id:"1", praia:"Vermelha do Centro", autor:"leandro", tamanho:"0,5m", vento:"Terral", texto:"Glass hoje cedo", foto:"https://images.unsplash.com/photo-1502680390542-bdb6c82a8aea?w=800&h=500&fit=crop", createdAt:new Date(Date.now()-60000*5).toISOString() },
      { id:"2", praia:"Itamambuca", autor:"dudu", tamanho:"1,0m", vento:"Maral", texto:"Cavado e irado", foto:"https://images.unsplash.com/photo-1502680393104-0bdd05f53aa8?w=800&h=500&fit=crop", createdAt:new Date(Date.now()-60000*12).toISOString() },
      { id:"3", praia:"Perequê Açú", autor:"ss", tamanho:"1,0m", vento:"Terral", texto:"Quase 1m glass", foto:"https://images.unsplash.com/photo-1502680393104-0bdd05f53aa8?w=800&h=500&fit=crop", createdAt:new Date().toISOString() },
    ];
  });
  const [cams]=useState<Cam[]>(()=>{const s=localStorage.getItem("ms-ubatuba-cams-v3"); return s?JSON.parse(s):[];});
  const [praiaSel,setPraiaSel]=useState(PRAIAS[2]); const [autor,setAutor]=useState(""); const [tamanho,setTamanho]=useState("0,5m"); const [vento,setVento]=useState("Terral"); const [texto,setTexto]=useState(""); const [aoVivoUrl,setAoVivoUrl]=useState(""); const [fotoPreview,setFotoPreview]=useState(""); const [filtro,setFiltro]=useState("Todas");
  const [leftOpen,setLeftOpen]=useState({reg:true, prev:false, picos:false});
  const [tabMeio,setTabMeio]=useState("posts");
  const [picosData,setPicosData]=useState<PicoData[]>([]);
  const [praiaCarrosselIdx,setPraiaCarrosselIdx]=useState(0);
  const [postCarrosselIdx,setPostCarrosselIdx]=useState(0);
  const [ondaCarrosselIdx,setOndaCarrosselIdx]=useState(0);
  const [bannerIdx,setBannerIdx]=useState(0);
  const fileRef=useRef<HTMLInputElement>(null);
  useEffect(()=>{localStorage.setItem("ms-ubatuba-reports-v3",JSON.stringify(reports));},[reports]);
  useEffect(()=>{
    const mock = PRAIAS.map(p=>{
      const c = COORDS[p]; const rnd = (Math.random()*1.0+0.3);
      const tend = ["subindo","descendo","estavel"][Math.floor(Math.random()*3)] as PicoData["tendencia"];
      return { praia: p, onda: rnd.toFixed(1)+"m", vento: ["Terral","Maral"][Math.floor(Math.random()*2)], periodo: (Math.floor(Math.random()*6+7)) + "s", mare: (Math.random()*1.2+0.3).toFixed(1) + "m", tendencia: tend, variacao: tend==="subindo"? "+"+(Math.random()*0.4).toFixed(1):tend==="descendo"? "-"+(Math.random()*0.4).toFixed(1):"0,0", fundo: c.fundo, nivel: c.nivel, crowd: ["Baixo","Médio"][Math.floor(Math.random()*2)] };
    });
    setPicosData(mock);
  },[]);
  useEffect(()=>{ const id = setInterval(()=>{ setPraiaCarrosselIdx(i=>(i+1)%PRAIAS.length); }, 4000); return ()=>clearInterval(id); },[]);
  useEffect(()=>{ const id = setInterval(()=>{ setPostCarrosselIdx(i=> (i+1)%Math.max(1,reports.filter(r=>filtro==="Todas"||r.praia===filtro).length)); }, 4000); return ()=>clearInterval(id); },[reports,filtro]);
  useEffect(()=>{ const id = setInterval(()=>{ setOndaCarrosselIdx(i=> (i+1)%Math.max(1,reports.length)); }, 3500); return ()=>clearInterval(id); },[reports]);
  useEffect(()=>{ const id = setInterval(()=>{ setBannerIdx(i=> (i+1)%3); }, 5000); return ()=>clearInterval(id); },[]);
  const handleFile=(e:any)=>{const f=e.target.files?.[0]; if(!f) return; const r=new FileReader(); r.onload=()=>setFotoPreview(r.result as string); r.readAsDataURL(f);};
  const registrar=()=>{if(!fotoPreview){alert("Foto!"); return;} if(!autor){alert("Nome!"); return;} const novo={id:Date.now().toString(),praia:praiaSel,autor,tamanho,vento,texto:texto||"Condição agora",foto:fotoPreview,createdAt:new Date().toISOString(),aoVivoUrl:aoVivoUrl||undefined}; setReports([novo,...reports]); setTexto(""); setFotoPreview(""); setAoVivoUrl(""); setAutor("");};
  const filtrados=filtro==="Todas"?reports:reports.filter(r=>r.praia===filtro);
  const picosFiltrados = filtro==="Todas"?picosData:picosData.filter(p=>p.praia===filtro);
  const praiaAtual = picosData[praiaCarrosselIdx];
  return (
    <div className="min-h-screen md:h-screen md:overflow-hidden overflow-auto bg-[#f7f5e8] text-slate-800 font-sans flex flex-col">
      <div className="w-full bg-gradient-to-r from-[#4fb3d9] to-[#4dbb8a] text-white px-4 py-2 flex justify-between items-center shrink-0">
        <div className="flex items-center gap-2"><div className="w-6 h-6 rounded-full bg-white text-[#4fb3d9] font-black flex items-center justify-center text-xs">M</div><span className="font-black text-[12px]">MY SURF UBATUBA - 11 praias</span></div>
        <div className="font-black text-[12px] bg-white/20 px-3 py-1 rounded-full">UBATUBA Capital do Surf</div>
        <div className="text-[10px] hidden md:block">24°C • Toledo 77 • Medina</div>
      </div>
      <div className="w-full bg-[#1a2a44] text-white px-3 py-1.5 flex items-center gap-3 shrink-0 border-b border-white/10">
        <div className="bg-[#ffcc00] text-black font-black text-[10px] px-3 py-1 rounded-full shrink-0 animate-pulse">ROLANDO ONDA AQUI ---&gt;</div>
        <div className="flex-1 overflow-hidden relative h-[22px]">
          <div className="absolute inset-0 flex items-center">
            {reports.length>0 ? (
              <div key={ondaCarrosselIdx} className="flex items-center gap-2 whitespace-nowrap">
                <span className="bg-white/20 px-2 py-0.5 rounded-full text-[9px]">🔥 AO VIVO</span>
                <span className="font-bold text-[11px] text-[#7ee0a0]">{INFORMAL[reports[ondaCarrosselIdx]?.praia] || reports[ondaCarrosselIdx]?.praia.toLowerCase()} - {TAMANHO_FALA[reports[ondaCarrosselIdx]?.tamanho] || reports[ondaCarrosselIdx]?.tamanho}</span>
                <span className="text-[10px] opacity-70">postado por <b className="text-white">{reports[ondaCarrosselIdx]?.autor}</b> • {reports[ondaCarrosselIdx]?.praia}</span>
                <span className="text-[9px] bg-blue-500 px-2 py-0.5 rounded-full">{reports[ondaCarrosselIdx]?.vento}</span>
              </div>
            ) : (<span className="text-[11px] opacity-60">Ninguém postou onda ainda - seja o primeiro! 🤙</span>)}
          </div>
        </div>
        <div className="text-[8px] opacity-60 shrink-0">{ondaCarrosselIdx+1}/{reports.length || 1} • 3.5s</div>
      </div>
      <div className="max-w-[1440px] w-full mx-auto px-3 py-1.5 flex gap-2 items-center shrink-0">
        <select value={filtro} onChange={e=>setFiltro(e.target.value)} className="px-2 py-1 rounded-full bg-white border text-[10px] font-bold"><option value="Todas">Todas ({reports.length})</option>{PRAIAS.map(p=><option key={p}>{p}</option>)}</select>
        <div className="flex-1 flex justify-center">
          <div className="flex items-center gap-2">
            {praiaAtual && (
              <div className={"flex items-center gap-2 px-4 py-1.5 rounded-full border-2 font-bold text-[11px] transition-all duration-500 "+(praiaAtual.tendencia==="subindo"?"bg-blue-500 text-white border-blue-600":praiaAtual.tendencia==="descendo"?"bg-red-500 text-white border-red-600":"bg-white text-black border-slate-300")}>
                <span>{praiaAtual.praia}</span>
                <span className="bg-white text-black px-2 py-0.5 rounded-full text-[10px]">{praiaAtual.onda}</span>
                <span className="text-[14px]">{praiaAtual.tendencia==="subindo"?"↗":praiaAtual.tendencia==="descendo"?"↘":"→"}</span>
                <span className="text-[10px]">{praiaAtual.variacao}m</span>
                <span className="text-[9px] opacity-80">{praiaAtual.vento}</span>
                <span className="text-[8px] bg-black/20 px-1.5 py-0.5 rounded-full">{praiaCarrosselIdx+1}/11 • 4s</span>
              </div>
            )}
          </div>
        </div>
        <a href="/adm" className="px-2 py-1 rounded-full bg-black text-white text-[10px] font-bold">ADM</a>
      </div>
      <div className="max-w-[1440px] w-full mx-auto px-3 pb-20 md:pb-2 flex-1 md:overflow-hidden overflow-auto grid grid-cols-12 gap-2">
        <div className="col-span-12 md:col-span-3 h-auto md:h-full md:overflow-hidden flex flex-col gap-2 order-2 md:order-1">
          <div className="bg-white rounded-[14px] border shadow-sm overflow-hidden flex flex-col">
            <button onClick={()=>setLeftOpen(s=>({...s, reg:!s.reg}))} className="flex justify-between items-center px-3 py-2 bg-[#2a5bd7] text-white text-[10px] font-black w-full group relative"><span className="flex items-center gap-2"><span className="w-6 h-6 bg-white/20 rounded-full flex items-center justify-center group-hover:bg-white group-hover:text-[#2a5bd7] transition">🏄‍♂️</span>1 - Registrar Onda</span><span>{leftOpen.reg?"▲":"▼"}</span></button>
            {leftOpen.reg && (<div className="p-2"><div className="flex gap-1 mb-2"><div className="group relative flex-1"><div className="w-full h-8 bg-[#f0f7ff] border border-[#2a5bd7]/30 rounded-lg flex items-center justify-center text-[14px] cursor-pointer hover:bg-[#2a5bd7] hover:text-white transition">📍</div></div><div className="group relative flex-1"><div className="w-full h-8 bg-[#f0fff4] border border-green-500/30 rounded-lg flex items-center justify-center text-[14px] cursor-pointer hover:bg-green-500 hover:text-white transition">🌊</div></div><div className="group relative flex-1"><div className="w-full h-8 bg-[#fff7ed] border border-orange-500/30 rounded-lg flex items-center justify-center text-[14px] cursor-pointer hover:bg-orange-500 hover:text-white transition">💨</div></div></div><select value={praiaSel} onChange={e=>setPraiaSel(e.target.value)} className="w-full px-2 py-2 rounded-xl border bg-white text-xs font-bold mb-2">{PRAIAS.map(p=><option key={p}>{p}</option>)}</select><div className="grid grid-cols-2 gap-1 mb-2"><select value={tamanho} onChange={e=>setTamanho(e.target.value)} className="px-2 py-1.5 rounded-xl border bg-white text-xs"><option>0,5m</option><option>0,8m</option><option>1,0m</option><option>1,5m</option><option>2,0m</option></select><select value={vento} onChange={e=>setVento(e.target.value)} className="px-2 py-1.5 rounded-xl border bg-white text-xs"><option>Terral</option><option>Maral</option></select></div><textarea value={texto} onChange={e=>setTexto(e.target.value)} placeholder="Como tá o mar?" className="w-full h-[50px] rounded-xl border bg-white px-2 py-1.5 text-xs resize-none" /><button onClick={()=>fileRef.current?.click()} className="w-full mt-2 py-1.5 rounded-full bg-[#5bb8e3]/20 border border-[#5bb8e3] text-[#2a5bd7] text-[10px] font-bold">📷 Foto prova</button><input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleFile} />{fotoPreview && <img src={fotoPreview} className="w-full h-20 object-cover rounded-xl mt-1 border"/>}<input value={autor} onChange={e=>setAutor(e.target.value)} placeholder="Seu nome" className="w-full rounded-xl border px-2 py-1.5 text-xs bg-white mt-1" /><input value={aoVivoUrl} onChange={e=>setAoVivoUrl(e.target.value)} placeholder="Live pequena" className="w-full rounded-xl border px-2 py-1 text-[10px] bg-white mt-1" /><button onClick={registrar} className="w-full mt-2 rounded-full bg-gradient-to-r from-[#3b82f6] to-[#22c55e] text-white font-black py-2 text-xs">🏄‍♂️ Registrar</button></div>)}
          </div>
          <div className="bg-white rounded-[14px] border shadow-sm overflow-hidden flex flex-col"><button onClick={()=>setLeftOpen(s=>({...s, prev:!s.prev}))} className="flex justify-between items-center px-3 py-2 bg-white text-[#2a5bd7] text-[10px] font-black w-full border-b group relative"><span className="flex items-center gap-2"><span className="w-6 h-6 bg-[#f7f5e8] border rounded-full flex items-center justify-center group-hover:bg-[#2a5bd7] group-hover:text-white transition">📊</span>2 - Prev Semanal</span><span>{leftOpen.prev?"▲":"▼"}</span></button>{leftOpen.prev && (<div className="p-2"><GraficoOndaVentoMare data={GRAFICO_HOJE} /><div className="grid grid-cols-7 gap-1 mt-2">{["Seg 0,8","Ter 1,2","Qua 1,5","Qui 1,0","Sex 0,6","Sáb 1,3","Dom 1,1"].map(d=><div key={d} className="bg-[#f7f5e8] rounded-lg p-1 text-center border text-[8px] font-bold">{d}</div>)}</div></div>)}</div>
          <div className="bg-white rounded-[14px] border shadow-sm overflow-hidden flex-1 flex flex-col"><button onClick={()=>setLeftOpen(s=>({...s, picos:!s.picos}))} className="flex justify-between items-center px-3 py-2 bg-white text-[#2a5bd7] text-[10px] font-black w-full border-b shrink-0 group relative"><span className="flex items-center gap-2"><span className="w-6 h-6 bg-[#f7f5e8] border rounded-full flex items-center justify-center group-hover:bg-[#2a5bd7] group-hover:text-white transition">📍</span>3 - Picos de Onda</span><span>{leftOpen.picos?"▲":"▼"}</span></button>{leftOpen.picos && (<div className="flex-1 overflow-auto p-2 space-y-1.5">{picosFiltrados.map(p=>(<div key={p.praia} className="rounded-xl border p-1.5 bg-[#f7f5e8]"><div className="flex justify-between"><p className="font-black text-[9px] text-[#2a5bd7]">{p.praia}</p><span className={"text-[9px] font-bold "+(p.tendencia==="subindo"?"text-blue-600":p.tendencia==="descendo"?"text-red-600":"text-slate-500")}>{p.tendencia==="subindo"?"↗":p.tendencia==="descendo"?"↘":"→"} {p.variacao}</span></div><div className="grid grid-cols-3 gap-1 mt-1 text-[9px]"><div className="bg-white rounded-lg p-1 text-center border"><p className="opacity-60 text-[7px]">ONDA</p><p className="font-bold">{p.onda}</p></div><div className="bg-white rounded-lg p-1 text-center border"><p className="opacity-60 text-[7px]">VENTO</p><p className="font-bold">{p.vento}</p></div><div className="bg-white rounded-lg p-1 text-center border"><p className="opacity-60 text-[7px]">MARÉ</p><p className="font-bold">{p.mare}</p></div></div></div>))}</div>)}</div>
        </div>
        <div className="col-span-12 md:col-span-6 h-auto md:h-full md:overflow-hidden flex flex-col gap-2 order-1 md:order-2">
          <div className="bg-white rounded-[12px] border shadow-sm overflow-hidden flex h-[145px] shrink-0 relative">
            <div className="absolute inset-0 flex">
              {bannerIdx===0 && (<><div className="w-1/2 h-full overflow-hidden"><img src={BG_PONTO} className="w-full h-full object-cover object-center" /></div><div className="w-1/2 h-full overflow-hidden"><img src={BG_MEDINA} className="w-full h-full object-cover object-center" /></div></>)}
              {bannerIdx===1 && (<><div className="w-1/2 h-full overflow-hidden"><img src={BG_SLATER} className="w-full h-full object-cover object-center" /></div><div className="w-1/2 h-full overflow-hidden"><img src={BG_ANDY} className="w-full h-full object-cover object-center" /></div></>)}
              {bannerIdx===2 && (<><div className="w-1/2 h-full overflow-hidden"><img src={BG_JOHN} className="w-full h-full object-cover object-center" /></div><div className="w-1/2 h-full overflow-hidden"><img src={BG_ITALO} className="w-full h-full object-cover object-top" /></div></>)}
            </div>
            <div className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-1 z-10"><div className={"w-2 h-2 rounded-full "+(bannerIdx===0?"bg-white":"bg-white/40")}></div><div className={"w-2 h-2 rounded-full "+(bannerIdx===1?"bg-white":"bg-white/40")}></div><div className={"w-2 h-2 rounded-full "+(bannerIdx===2?"bg-white":"bg-white/40")}></div></div>
            <div className="absolute top-1 left-2 bg-black/60 text-white text-[7px] px-2 py-0.5 rounded-full z-10">{bannerIdx===0?"TOLEDO 77 + MEDINA":bannerIdx===1?"SLATER + ANDY IRONS":"JOHN JOHN + ITALO"} • {bannerIdx+1}/3 • 5s</div>
          </div>
          <div className="bg-white rounded-[12px] border shadow-sm p-1.5 flex gap-1 overflow-x-auto shrink-0">
            <button onClick={()=>setTabMeio("posts")} className={"px-3 py-1 rounded-full text-[10px] font-bold border "+(tabMeio==="posts"?"bg-slate-900 text-white":"bg-[#fdf8e8]")}>Posts • {postCarrosselIdx+1}/{filtrados.length || 1} ⏱ 4s</button>
            <button onClick={()=>setTabMeio("picos")} className={"px-3 py-1 rounded-full text-[10px] font-bold border "+(tabMeio==="picos"?"bg-slate-900 text-white":"bg-[#fdf8e8]")}>Picos</button>
            <button onClick={()=>setTabMeio("lives")} className={"px-3 py-1 rounded-full text-[10px] font-bold border "+(tabMeio==="lives"?"bg-slate-900 text-white":"bg-[#fdf8e8]")}>Lives</button>
            <button onClick={()=>setTabMeio("noticias")} className={"px-3 py-1 rounded-full text-[10px] font-bold border "+(tabMeio==="noticias"?"bg-slate-900 text-white":"bg-[#fdf8e8]")}>Notícias</button>
          </div>
          <div className="flex-1 overflow-hidden bg-white rounded-[12px] border shadow-sm flex flex-col min-h-[420px] md:min-h-0">
            <div className="flex-1 overflow-auto p-2 space-y-3">
              {tabMeio==="posts" && filtrados.length>0 && (
                <div key={filtrados[postCarrosselIdx]?.id || postCarrosselIdx} className="bg-white rounded-[12px] border-2 border-[#2a5bd7]/20 overflow-hidden">
                  <div className="flex items-center gap-2 p-2 bg-[#f7f5e8]"><div className="w-7 h-7 rounded-full bg-gradient-to-br from-[#5bb8e3] to-[#4dbb8a] text-white font-black flex items-center justify-center text-[10px]">{filtrados[postCarrosselIdx]?.autor[0]?.toUpperCase()}</div><div className="flex-1"><p className="font-bold text-[11px]">{filtrados[postCarrosselIdx]?.autor} • {filtrados[postCarrosselIdx]?.praia}</p><p className="text-[9px] opacity-60">{new Date(filtrados[postCarrosselIdx]?.createdAt).toLocaleTimeString("pt-BR")} • {filtrados[postCarrosselIdx]?.tamanho} • {filtrados[postCarrosselIdx]?.vento}</p></div><span className="text-[8px] bg-[#2a5bd7] text-white px-2 py-1 rounded-full">{postCarrosselIdx+1}/{filtrados.length}</span></div>
                  <div className="w-full bg-black flex items-center justify-center"><img src={filtrados[postCarrosselIdx]?.foto} className="w-full h-[320px] md:h-[280px] object-cover object-center" /></div>
                  <div className="p-3"><p className="text-[11px]"><b>{filtrados[postCarrosselIdx]?.autor}</b> {filtrados[postCarrosselIdx]?.texto}</p></div>
                </div>
              )}
              {tabMeio==="posts" && filtrados.length===0 && <p className="text-center text-[12px] opacity-50 p-4">Nenhum post ainda</p>}
              {tabMeio==="picos" && (<div className="grid grid-cols-2 gap-1.5">{picosFiltrados.map(p=>(<div key={p.praia} className="rounded-lg border bg-[#fdf8e8] p-2"><p className="font-black text-[10px] text-[#2a5bd7]">{p.praia}</p><div className="grid grid-cols-3 gap-1 mt-1 text-[9px]"><div className="bg-white rounded p-1 text-center border"><p className="text-[7px]">ONDA</p><p className="font-bold">{p.onda}</p></div><div className="bg-white rounded p-1 text-center border"><p className="text-[7px]">VENTO</p><p className="font-bold">{p.vento}</p></div><div className="bg-white rounded p-1 text-center border"><p className="text-[7px]">MARÉ</p><p className="font-bold">{p.mare}</p></div></div></div>))}</div>)}
              {tabMeio==="lives" && (<div className="grid grid-cols-2 gap-1.5">{cams.map((cam:any)=>{const embed=getYoutubeEmbed(cam.liveUrl); return (<div key={cam.id} className="rounded-lg overflow-hidden bg-[#1e3a5f]"><div className="h-[90px]">{embed ? <iframe src={embed} className="w-full h-full" allowFullScreen></iframe> : <button onClick={()=>window.open(cam.liveUrl,"_blank")} className="w-full h-full text-white text-[10px]">▶ {cam.plataforma}</button>}</div><div className="p-1"><p className="text-white text-[9px]">{cam.label}</p></div></div>);})}{cams.length===0 && <p className="text-[10px] opacity-60 col-span-2 text-center p-2 border rounded-lg border-dashed">Nenhuma live</p>}</div>)}
              {tabMeio==="noticias" && (<div className="space-y-1.5">{NOTICIAS.map(n=>(<div key={n.id} className="rounded-lg border overflow-hidden flex"><img src={n.foto} className="w-[80px] h-[60px] object-cover"/><div className="p-2 flex-1"><p className="font-black text-[10px]">{n.titulo}</p><p className="text-[9px] opacity-70">{n.resumo}</p></div></div>))}</div>)}
            </div>
          </div>
        </div>
        <div className="col-span-12 md:col-span-3 h-auto md:h-full md:overflow-hidden flex flex-col order-3">
          <div className="bg-[#fdf8e8] rounded-[12px] border shadow-sm p-2 flex-1 overflow-hidden flex flex-col">
            <h3 className="font-black text-[#2a5bd7] text-[11px] mb-2 flex items-center gap-1">📸 FOTOS DA GALERA <span className="bg-[#2a5bd7] text-white text-[8px] px-1.5 py-0.5 rounded-full">{filtrados.length}</span></h3>
            <div className="grid grid-cols-2 gap-2 overflow-auto flex-1 content-start">
              {filtrados.map(r=>(<div key={r.id} className="rounded-xl overflow-hidden border-2 border-white shadow-sm bg-white group hover:border-[#2a5bd7] transition cursor-pointer"><div className="w-full h-[85px] overflow-hidden bg-black/5 flex items-center justify-center"><img src={r.foto} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" /></div><div className="p-1.5"><p className="font-black text-[9px] truncate text-[#2a5bd7]">{INFORMAL[r.praia] || r.praia}</p><p className="text-[8px] opacity-70 truncate">{r.tamanho} • {r.autor}</p><p className="text-[7px] bg-[#ffcc00]/30 px-1 py-0.5 rounded-full mt-0.5 inline-block">{r.vento}</p></div></div>))}
              {filtrados.length===0 && <p className="col-span-2 text-center text-[10px] opacity-50 p-4">Sem fotos ainda</p>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
